void owned_reads(){
    const auto select=[](const auto& object)->decltype(auto){return (object.name);};
    auto make=[](){return V(V::Object{{"name",V("Owned")}});};
    check(lvui::native::initial(lvui::native::named_member(make(),"name",select))==V("Owned"),"Initial data member borrowed a temporary");
    lvui::native::Bindings graph;ii::core::Observable<std::uint64_t> revision{0};int evaluations=0;V shown;
    auto binding=graph.bind([&](lvui::native::ReadContext& context){
        ++evaluations;
        auto value=lvui::native::read_source(context,lvui::native::named_member(make(),"name",select));
        auto direct=lvui::native::read(context,V(3),revision);
        check(direct==V(3),"Owned native read lost its temporary value");return value;
    },[&](V value)->ii::core::Result<void>{shown=std::move(value);return {};});
    check(binding&&shown==V("Owned")&&evaluations==1,"Reactive data member did not own its result");
    auto stats=graph.stats();check(stats&&stats->sources==1,"Owned native read did not subscribe to the backend revision");
    revision.set(1);
    check(evaluations==2&&shown==V("Owned")&&graph.failures()->empty(),"Owned native read did not update after backend revision publication");
    int native=4;static_assert(std::is_lvalue_reference_v<decltype(lvui::native::initial(native))>);lvui::native::initial(native)=7;check(native==7,"Owned overload changed C++ lvalue reference");
    auto text=lvui::native::initial(std::string_view("Stable"));static_assert(std::same_as<decltype(text),std::string>);check(text=="Stable","Temporary text view did not materialize");
}

